using ModelContextProtocol.Client;
using ModelContextProtocol.Protocol;
using Repl.Mcp;

namespace Repl.McpTests;

[TestClass]
public sealed class Given_McpIntegration
{
	[TestMethod]
	[Description("UseMcpServer registers the 'mcp serve' route on the app.")]
	public void When_UseMcpServer_Then_McpServeRouteIsRegistered()
	{
		var app = ReplApp.Create();
		app.Map("hello", () => "world");
		app.UseMcpServer();

		// Resolve through the internal CoreReplApp to verify routing.
		var match = app.Core.Resolve(["mcp", "serve"]);

		match.Should().NotBeNull();
		match!.Route.Command.IsProtocolPassthrough.Should().BeTrue();
	}

	[TestMethod]
	[Description("UseMcpServer with custom command name uses that name.")]
	public void When_CustomContextName_Then_RouteUsesCustomName()
	{
		var app = ReplApp.Create();
		app.Map("hello", () => "world");
		app.UseMcpServer(o => o.ContextName = "ai");

		var match = app.Core.Resolve(["ai", "serve"]);

		match.Should().NotBeNull();
	}

	[TestMethod]
	[Description("MCP serve route is hidden from discovery.")]
	public void When_UseMcpServer_Then_McpContextIsHidden()
	{
		var app = ReplApp.Create();
		app.Map("hello", () => "world");
		app.UseMcpServer();

		var model = app.CreateDocumentationModel();

		model.Commands.Should().NotContain(c => string.Equals(c.Path, "mcp serve", StringComparison.Ordinal));
	}

	[TestMethod]
	[Description("MCP protocol passthrough help remains hidden from root discovery but is visible when users ask for the MCP scope or command help.")]
	public void When_McpHelpIsRequested_Then_ProtocolServeCommandIsShown()
	{
		var app = ReplApp.Create().UseDefaultInteractive();
		app.UseMcpServer();

		var rootHelp = app.Core.BuildHumanHelp([]);
		var mcpHelp = app.Core.BuildHumanHelp(["mcp"]);
		var serveHelp = app.Core.BuildHumanHelp(["mcp", "serve"]);

		rootHelp.Should().NotContain("mcp serve");
		mcpHelp.Should().Contain("Commands:");
		mcpHelp.Should().Contain("serve");
		mcpHelp.Should().NotContain("(none)");
		serveHelp.Should().Contain("Usage: mcp serve");
		serveHelp.Should().Contain("Start MCP stdio server for agent integration.");
	}

	[TestMethod]
	[Description("MCP server options advertise logging capability because interaction feedback can be routed through MCP notifications.")]
	public void When_BuildingMcpOptions_Then_LoggingCapabilityIsAdvertised()
	{
		var app = ReplApp.Create();
		app.UseMcpServer();

		var options = app.BuildMcpServerOptions();

		// Logging is deprecated (SEP-2577, MCP9005) but still supported by Repl.Mcp (#51).
#pragma warning disable MCP9005
		options.Capabilities!.Logging.Should().NotBeNull();
#pragma warning restore MCP9005
	}

	[TestMethod]
	[Description("Commands marked AutomationHidden are excluded from MCP tool candidates.")]
	public void When_CommandIsAutomationHidden_Then_ExcludedFromToolCandidates()
	{
		var app = ReplApp.Create();
		app.Map("list", () => "ok").ReadOnly();
		app.Map("wizard", () => "ok").AutomationHidden();

		var model = app.CreateDocumentationModel();
		var toolCandidates = model.Commands.Where(c =>
			!c.IsHidden && c.Annotations?.AutomationHidden != true).ToList();

		toolCandidates.Should().ContainSingle(c => string.Equals(c.Path, "list", StringComparison.Ordinal));
		toolCandidates.Should().NotContain(c => string.Equals(c.Path, "wizard", StringComparison.Ordinal));
	}

	[TestMethod]
	[Description("Documentation model includes enriched metadata for MCP commands.")]
	public void When_EnrichedCommands_Then_DocModelContainsAllFields()
	{
		var app = ReplApp.Create();
		app.Map("deploy {env}", (string env) => $"Deployed to {env}")
			.WithDescription("Deploy application")
			.WithDetails("Deploys to the specified environment.")
			.Destructive()
			.OpenWorld()
			.LongRunning();
		app.UseMcpServer();

		var model = app.CreateDocumentationModel();
		var cmd = model.Commands.Single(c => string.Equals(c.Path, "deploy {env}", StringComparison.Ordinal));

		cmd.Description.Should().Be("Deploy application");
		cmd.Details.Should().Be("Deploys to the specified environment.");
		cmd.Annotations!.Destructive.Should().BeTrue();
		cmd.Annotations!.OpenWorld.Should().BeTrue();
		cmd.Annotations!.LongRunning.Should().BeTrue();
		cmd.Arguments.Should().ContainSingle(a => string.Equals(a.Name, "env", StringComparison.Ordinal));
	}

	[TestMethod]
	[Description("Regression guard: verifies the 2026-07-28 cache hints stay off an initialize-era response. CacheScope and TimeToLive were added by SEP-2549 and are absent from the legacy result schema, so a strict client on the compatibility path this PR exists to preserve can reject a response carrying them. Probed on tools; the handler tags all four list results through one helper.")]
	public async Task When_ClientPinsLegacyProtocolVersion_Then_ListResultsCarryNoCacheHints()
	{
		var clientOptions = new McpClientOptions
		{
			ProtocolVersion = "2025-11-25",
		};

		await using var fixture = await McpTestFixture.CreateAsync(
			app => app.Map("ping", () => "pong"),
			configureOptions: null,
			clientOptions: clientOptions);

		fixture.Client.NegotiatedProtocolVersion.Should().Be("2025-11-25");

		var tools = await fixture.Client.SendRequestAsync<ListToolsRequestParams, ListToolsResult>(
			RequestMethods.ToolsList, new ListToolsRequestParams(), cancellationToken: default).ConfigureAwait(false);

		tools.CacheScope.Should().BeNull(because: "cacheScope is a 2026-07-28 field");
		tools.TimeToLive.Should().BeNull();
	}

	[TestMethod]
	[Description("Locks the legacy initialize handshake under SDK 2.0: a client pinning an initialize-era protocol revision still negotiates that exact version and can list and call tools — the fixture's default client otherwise negotiates the 2026-07-28 path and never exercises the fallback.")]
	public async Task When_ClientPinsLegacyProtocolVersion_Then_InitializeHandshakeAndToolsWork()
	{
		var clientOptions = new McpClientOptions
		{
			ProtocolVersion = "2025-11-25",
		};

		await using var fixture = await McpTestFixture.CreateAsync(
			app => app.Map("ping", () => "pong"),
			configureOptions: null,
			clientOptions: clientOptions);

		fixture.Client.NegotiatedProtocolVersion.Should().Be("2025-11-25");

		var tools = await fixture.Client.ListToolsAsync().ConfigureAwait(false);
		tools.Should().ContainSingle(tool => string.Equals(tool.Name, "ping", StringComparison.Ordinal));

		var result = await fixture.Client.CallToolAsync(
			toolName: "ping",
			arguments: new Dictionary<string, object?>(StringComparer.Ordinal)).ConfigureAwait(false);
		result.Content.OfType<TextContentBlock>().First().Text.Should().Contain("pong");
	}

	[TestMethod]
	[Description("Locks the tools/list wire shape for .LongRunning(): the annotation is Repl-local metadata and must leave no trace on the protocol surface until Repl integrates the SDK Tasks extension (issue #72). Asserted by serializing two otherwise identical tools that differ only by .LongRunning() and requiring byte-identical payloads — a NotContain(\"execution\") assertion could not fail, since SDK 2.x removed Tool.Execution entirely.")]
	public void When_SerializingLongRunningTool_Then_WireShapeIsUnchanged()
	{
		var app = ReplApp.Create();
		app.Map("deploy", () => "deployed")
			.WithDescription("Deploy application")
			.LongRunning()
			.OpenWorld();
		app.Map("release", () => "released")
			.WithDescription("Deploy application")
			.OpenWorld();

		var options = app.BuildMcpServerOptions();

		SerializeTool(options, "deploy").Should().Be(
			SerializeTool(options, "release").Replace("\"release\"", "\"deploy\"", StringComparison.Ordinal),
			because: ".LongRunning() must not change anything a client can observe");
	}

	private static string SerializeTool(ModelContextProtocol.Server.McpServerOptions options, string name)
	{
		var tool = options.ToolCollection!.Single(tool =>
			string.Equals(tool.ProtocolTool.Name, name, StringComparison.Ordinal));

		return System.Text.Json.JsonSerializer.Serialize(
			tool.ProtocolTool, ModelContextProtocol.McpJsonUtilities.DefaultOptions);
	}

	[TestMethod]
	[Description("Modules excluded from Programmatic channel are not visible as MCP tools.")]
	public void When_ModuleExcludedFromProgrammatic_Then_NotInToolCandidates()
	{
		var app = ReplApp.Create();
		app.Map("public-cmd", () => "ok").ReadOnly();
		app.MapModule(
			new AdminModule(),
			ctx => ctx.Channel != ReplRuntimeChannel.Programmatic);
		app.UseMcpServer();

		// Simulate programmatic channel by setting the flag.
		ReplSessionIO.IsProgrammatic = true;
		try
		{
			var model = app.Core.CreateDocumentationModel();
			model.Commands.Should().NotContain(c => string.Equals(c.Path, "admin reset", StringComparison.Ordinal));
			model.Commands.Should().Contain(c => string.Equals(c.Path, "public-cmd", StringComparison.Ordinal));
		}
		finally
		{
			ReplSessionIO.IsProgrammatic = false;
		}
	}

	private sealed class AdminModule : IReplModule
	{
		public void Map(IReplMap map)
		{
			map.Map("admin reset", () => "reset done");
		}
	}
}

